/**
 * Token-styled scrollbar for a region that already scrolls (`design/components/scroll-area.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/scroll-area.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { Component, ViewEncapsulation, input } from '@angular/core'

import * as zag from '@zag-js/scroll-area'

import {
  MEMBER_PROVIDERS,
  Ref,
  SlotOutlet,
  SlotTemplate,
  Spread,
  classes,
  derived,
  elementRef,
  mergeParts,
  normalizeProps,
  setup,
  uniqueId,
  useDirection,
  useMachine,
  useMember,
} from '@polymorph/angular'
import styles from '@polymorph/recipes/structure/scroll-area.module.css'

export type ScrollAreaOrientation = NonNullable<ScrollAreaProps['orientation']>

export type ScrollAreaType = NonNullable<ScrollAreaProps['type']>

/** Token-styled scrollbar for a region that already scrolls: the inputs it takes, by the React member's prop names. */
export interface ScrollAreaProps {
  /**
   * Names the region for keyboard users once it overflows, as in CodeBlock. Required rather than
   * defaulted. The content identifies the region, but a default name would be in one fixed
   * language, and the app's language is unknown here.
   */
  label: string
  /**
   * Which axes may pan; `'both'` draws two rails and the corner.
   */
  orientation?: 'horizontal' | 'vertical' | 'both'
  type?: 'hover' | 'always'
}

/** Token-styled scrollbar for a region that already scrolls. */
@Component({
  selector: 'pm-scroll-area',
  encapsulation: ViewEncapsulation.None,
  host: { style: 'display: contents' },
  providers: [...MEMBER_PROVIDERS],
  imports: [Ref, SlotOutlet, SlotTemplate, Spread],
  // prettier-ignore
  template: `<ng-template pmSlot="default" [pmSlotOf]="$"><ng-content /></ng-template>
<div
[pmSpread]="e1()"
[pmRef]="root"
><div
[pmSpread]="e2()"
><div
[pmSpread]="e3()"
><ng-container [pmSlotOutlet]="'default'" [pmSlotOf]="$" /></div></div>
@if (e4()) {@if (e5()) {<div
[pmSpread]="e6()"
><div
[pmSpread]="e7()"
></div></div>}}
@if (e8()) {@if (e9()) {<div
[pmSpread]="e10()"
><div
[pmSpread]="e11()"
></div></div>}}
@if (e12()) {<div
[pmSpread]="e13()"
></div>}</div>`,
})
export class ScrollArea {
  /**
   * Names the region for keyboard users once it overflows, as in CodeBlock. Required rather than
   * defaulted. The content identifies the region, but a default name would be in one fixed
   * language, and the app's language is unknown here.
   */
  readonly label = input.required<ScrollAreaProps['label']>()
  /**
   * Which axes may pan; `'both'` draws two rails and the corner.
   */
  readonly orientation = input<
    Exclude<ScrollAreaProps['orientation'], undefined>,
    ScrollAreaProps['orientation']
  >('vertical', {
    transform: (value: ScrollAreaProps['orientation']) =>
      value === undefined ? 'vertical' : value,
  })
  readonly type = input<Exclude<ScrollAreaProps['type'], undefined>, ScrollAreaProps['type']>(
    'always',
    { transform: (value: ScrollAreaProps['type']) => (value === undefined ? 'always' : value) },
  )
  protected readonly $ = useMember({
    events: [],
    props: {
      label: () => this.label(),
      orientation: () => this.orientation(),
      type: () => this.type(),
    },
  })
  protected readonly $p = this.$.props
  protected readonly uid = uniqueId()
  protected readonly root = elementRef<HTMLElement>()
  protected readonly fades = derived(() => this.$p.type === 'hover')
  protected readonly documentDirection = useDirection(() => this.root.value)
  protected readonly service: { readonly value: zag.Service } = setup(() =>
    useMachine(
      zag.machine,
      () => ({ id: this.uid, dir: this.documentDirection() }) as Partial<zag.Props>,
    ),
  )
  protected readonly api: { readonly value: ReturnType<typeof zag.connect> } = derived(() =>
    zag.connect(this.service.value, normalizeProps),
  )
  protected readonly overflowing = derived(
    () => this.api.value.hasOverflowX || this.api.value.hasOverflowY,
  )

  protected e1() {
    return mergeParts(this.api.value.getRootProps(), {
      class: styles.root,
      'data-member': 'scroll-area',
    })
  }

  protected e2() {
    return mergeParts(this.api.value.getViewportProps(), {
      class: styles.viewport,
      style: {
        'overflow-x': this.$p.orientation === 'vertical' ? 'hidden' : 'scroll',
        'overflow-y': this.$p.orientation === 'horizontal' ? 'hidden' : 'scroll',
        'scrollbar-width': 'none',
      },
      tabindex: this.overflowing.value ? 0 : undefined,
      role: this.overflowing.value ? 'region' : undefined,
      'aria-label': this.overflowing.value ? this.$p.label : undefined,
    })
  }

  protected e3() {
    return mergeParts(this.api.value.getContentProps())
  }

  protected e4() {
    return this.$p.orientation === 'both' || this.$p.orientation === 'vertical'
  }

  protected e5() {
    if (!(this.$p.orientation === 'both' || this.$p.orientation === 'vertical'))
      return undefined as never
    return this.api.value.hasOverflowY
  }

  protected e6() {
    if (!(this.$p.orientation === 'both' || this.$p.orientation === 'vertical'))
      return undefined as never
    if (!this.api.value.hasOverflowY) return undefined as never
    return mergeParts(this.api.value.getScrollbarProps({ orientation: 'vertical' }), {
      class: classes(
        styles.rail,
        this.fades.value ? styles.hover : undefined,
        !this.fades.value ? styles.always : undefined,
      ),
      'aria-hidden': 'true',
      'data-state': this.fades.value
        ? this.api.value.getScrollbarState({ orientation: 'vertical' }).hovering ||
          this.api.value.getScrollbarState({ orientation: 'vertical' }).scrolling
          ? 'visible'
          : 'hidden'
        : undefined,
    })
  }

  protected e7() {
    if (!(this.$p.orientation === 'both' || this.$p.orientation === 'vertical'))
      return undefined as never
    if (!this.api.value.hasOverflowY) return undefined as never
    return mergeParts(this.api.value.getThumbProps({ orientation: 'vertical' }), {
      class: styles.thumb,
    })
  }

  protected e8() {
    return this.$p.orientation === 'both' || this.$p.orientation === 'horizontal'
  }

  protected e9() {
    if (!(this.$p.orientation === 'both' || this.$p.orientation === 'horizontal'))
      return undefined as never
    return this.api.value.hasOverflowX
  }

  protected e10() {
    if (!(this.$p.orientation === 'both' || this.$p.orientation === 'horizontal'))
      return undefined as never
    if (!this.api.value.hasOverflowX) return undefined as never
    return mergeParts(this.api.value.getScrollbarProps({ orientation: 'horizontal' }), {
      class: classes(
        styles.rail,
        this.fades.value ? styles.hover : undefined,
        !this.fades.value ? styles.always : undefined,
      ),
      'aria-hidden': 'true',
      'data-state': this.fades.value
        ? this.api.value.getScrollbarState({ orientation: 'horizontal' }).hovering ||
          this.api.value.getScrollbarState({ orientation: 'horizontal' }).scrolling
          ? 'visible'
          : 'hidden'
        : undefined,
    })
  }

  protected e11() {
    if (!(this.$p.orientation === 'both' || this.$p.orientation === 'horizontal'))
      return undefined as never
    if (!this.api.value.hasOverflowX) return undefined as never
    return mergeParts(this.api.value.getThumbProps({ orientation: 'horizontal' }), {
      class: styles.thumb,
    })
  }

  protected e12() {
    return this.$p.orientation === 'both'
  }

  protected e13() {
    if (!(this.$p.orientation === 'both')) return undefined as never
    return mergeParts(this.api.value.getCornerProps(), {
      class: styles.corner,
      'aria-hidden': 'true',
    })
  }
}
